{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2125-02-16 00:19:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I understand you've been feeling nauseous and vomiting since this morning?"
    },
    {
      "turn_number": 2,
      "time": "2125-02-16 00:21:00",
      "speaker": "Patient",
      "text": "Yes, right after I took my pills on an empty stomach. I couldn’t keep anything down all day."
    },
    {
      "turn_number": 3,
      "time": "2125-02-16 00:23:00",
      "speaker": "Doctor",
      "text": "I see. You went to the ER earlier and got fluids, Zofran, and Dilaudid. But the nausea didn’t improve much?"
    },
    {
      "turn_number": 4,
      "time": "2125-02-16 00:25:00",
      "speaker": "Patient",
      "text": "No, not really. I still felt sick. The Zofran ODT didn’t help at all."
    },
    {
      "turn_number": 5,
      "time": "2125-02-16 00:27:00",
      "speaker": "Doctor",
      "text": "Okay. Any belly pain, diarrhea, or constipation?"
    },
    {
      "turn_number": 6,
      "time": "2125-02-16 00:28:00",
      "speaker": "Patient",
      "text": "No stomach pain. Just my usual back pain. But I’ve been nauseous all day."
    },
    {
      "turn_number": 7,
      "time": "2125-02-16 00:30:00",
      "speaker": "Doctor",
      "text": "Got it. Your labs came back — no infection, no kidney issues, and your glucose was 87 when you arrived. That’s good."
    },
    {
      "turn_number": 8,
      "time": "2125-02-16 00:32:00",
      "speaker": "Patient",
      "text": "So it’s not DKA or anything serious?"
    },
    {
      "turn_number": 9,
      "time": "2125-02-16 00:34:00",
      "speaker": "Doctor",
      "text": "No, not this time. Your anion gap is normal, so we’re not worried about ketoacidosis."
    },
    {
      "turn_number": 10,
      "time": "2125-02-16 00:36:00",
      "speaker": "Patient",
      "text": "That’s a relief. But why does this keep happening?"
    },
    {
      "turn_number": 11,
      "time": "2125-02-16 00:38:00",
      "speaker": "Doctor",
      "text": "Given your history, it’s likely related to your gastroparesis — delayed stomach emptying from diabetes."
    },
    {
      "turn_number": 12,
      "time": "2125-02-16 00:40:00",
      "speaker": "Patient",
      "text": "So my stomach just doesn’t move food along?"
    },
    {
      "turn_number": 13,
      "time": "2125-02-16 00:42:00",
      "speaker": "Doctor",
      "text": "Exactly. And taking meds on an empty stomach can trigger nausea. We’ll keep you on bowel rest tonight — no food, just IV fluids."
    },
    {
      "turn_number": 14,
      "time": "2125-02-16 00:44:00",
      "speaker": "Patient",
      "text": "Okay, that makes sense. Will I be able to eat tomorrow?"
    },
    {
      "turn_number": 15,
      "time": "2125-02-16 00:46:00",
      "speaker": "Doctor",
      "text": "We’ll start with small sips in the morning. If you tolerate that, we’ll try light food."
    },
    {
      "turn_number": 16,
      "time": "2125-02-16 00:48:00",
      "speaker": "Patient",
      "text": "And my insulin? I’m worried about my sugars."
    },
    {
      "turn_number": 17,
      "time": "2125-02-16 00:50:00",
      "speaker": "Doctor",
      "text": "We’re monitoring your fingersticks. Since you’re not eating, we lowered your Lantus to 24 units tonight to avoid low sugars."
    },
    {
      "turn_number": 18,
      "time": "2125-02-16 00:52:00",
      "speaker": "Patient",
      "text": "I usually take 28 at night. Is it safe to go lower?"
    },
    {
      "turn_number": 19,
      "time": "2125-02-16 00:54:00",
      "speaker": "Doctor",
      "text": "Yes, temporarily. Once you’re eating normally again, you’ll go back to 28."
    },
    {
      "turn_number": 20,
      "time": "2125-02-16 00:56:00",
      "speaker": "Patient",
      "text": "Okay, good. What about my other meds?"
    },
    {
      "turn_number": 21,
      "time": "2125-02-16 00:58:00",
      "speaker": "Doctor",
      "text": "You’re still getting your amoxicillin, levofloxacin, and pantoprazole for your H. pylori treatment."
    },
    {
      "turn_number": 22,
      "time": "2125-02-16 01:00:00",
      "speaker": "Patient",
      "text": "And Reglan? That usually helps with nausea."
    },
    {
      "turn_number": 23,
      "time": "2125-02-16 01:02:00",
      "speaker": "Doctor",
      "text": "We’re holding the oral Reglan for now since you can’t keep pills down. But we’ll restart it when you can eat."
    },
    {
      "turn_number": 24,
      "time": "2125-02-16 01:04:00",
      "speaker": "Patient",
      "text": "What about pain? My back’s been bothering me."
    },
    {
      "turn_number": 25,
      "time": "2125-02-16 01:06:00",
      "speaker": "Doctor",
      "text": "You can have tramadol as needed. We’ll avoid morphine — you’re allergic, right?"
    },
    {
      "turn_number": 26,
      "time": "2125-02-16 01:08:00",
      "speaker": "Patient",
      "text": "Yes, and Prochlorperazine too. Tramadol is fine."
    },
    {
      "turn_number": 27,
      "time": "2125-02-16 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. How are you feeling?"
    },
    {
      "turn_number": 28,
      "time": "2125-02-16 08:17:00",
      "speaker": "Patient",
      "text": "Better. I haven’t vomited since last night. Can I try some water?"
    },
    {
      "turn_number": 29,
      "time": "2125-02-16 08:19:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll start with ice chips and clear liquids. If that stays down, we’ll advance to a light meal."
    },
    {
      "turn_number": 30,
      "time": "2125-02-16 08:21:00",
      "speaker": "Patient",
      "text": "Great. And my blood sugar was low this morning — 46."
    },
    {
      "turn_number": 31,
      "time": "2125-02-16 08:23:00",
      "speaker": "Doctor",
      "text": "Yes, that was during the night. It confirms we did the right thing lowering your Lantus. We’ll keep monitoring."
    },
    {
      "turn_number": 32,
      "time": "2125-02-16 08:25:00",
      "speaker": "Patient",
      "text": "So I should keep it at 24 until I’m eating normally?"
    },
    {
      "turn_number": 33,
      "time": "2125-02-16 08:27:00",
      "speaker": "Doctor",
      "text": "Exactly. Once you’re back on regular meals, go back to 28 units at bedtime."
    },
    {
      "turn_number": 34,
      "time": "2125-02-16 14:30:00",
      "speaker": "Doctor",
      "text": "You did well with the clear liquids. Ready to try a soft meal?"
    },
    {
      "turn_number": 35,
      "time": "2125-02-16 14:32:00",
      "speaker": "Patient",
      "text": "Yes, I’m hungry. Maybe some toast and applesauce?"
    },
    {
      "turn_number": 36,
      "time": "2125-02-16 14:34:00",
      "speaker": "Doctor",
      "text": "Perfect. We’ll bring that shortly. And we’re restarting Reglan with meals to help with stomach emptying."
    },
    {
      "turn_number": 37,
      "time": "2125-02-17 07:00:00",
      "speaker": "Doctor",
      "text": "You’ve been doing really well — tolerating food, no nausea, no vomiting."
    },
    {
      "turn_number": 38,
      "time": "2125-02-17 07:02:00",
      "speaker": "Patient",
      "text": "I feel much better. Can I go home today?"
    },
    {
      "turn_number": 39,
      "time": "2125-02-17 07:04:00",
      "speaker": "Doctor",
      "text": "Yes, we’re discharging you. Just a few things to go over."
    },
    {
      "turn_number": 40,
      "time": "2125-02-17 07:06:00",
      "speaker": "Patient",
      "text": "Okay, what do I need to know?"
    },
    {
      "turn_number": 41,
      "time": "2125-02-17 07:08:00",
      "speaker": "Doctor",
      "text": "Continue all your meds, including the antibiotics for H. pylori. Take Reglan with meals, not four times a day."
    },
    {
      "turn_number": 42,
      "time": "2125-02-17 07:10:00",
      "speaker": "Patient",
      "text": "Got it. And my insulin?"
    },
    {
      "turn_number": 43,
      "time": "2125-02-17 07:12:00",
      "speaker": "Doctor",
      "text": "Keep Lantus at 24 units tonight. When your appetite is back to normal, increase it to 28."
    },
    {
      "turn_number": 44,
      "time": "2125-02-17 07:14:00",
      "speaker": "Patient",
      "text": "Will do. Any follow-up?"
    },
    {
      "turn_number": 45,
      "time": "2125-02-17 07:16:00",
      "speaker": "Doctor",
      "text": "Yes, see your primary doctor in a few weeks. Call if nausea returns or you can’t keep food down."
    },
    {
      "turn_number": 46,
      "time": "2125-02-17 07:18:00",
      "speaker": "Patient",
      "text": "And if I feel a low sugar coming on?"
    },
    {
      "turn_number": 47,
      "time": "2125-02-17 07:20:00",
      "speaker": "Doctor",
      "text": "Treat it with fast-acting sugar — juice or glucose tabs. And check your levels four times a day."
    },
    {
      "turn_number": 48,
      "time": "2125-02-17 07:22:00",
      "speaker": "Patient",
      "text": "I have my meter with me. I’ll keep up with that."
    },
    {
      "turn_number": 49,
      "time": "2125-02-17 07:24:00",
      "speaker": "Doctor",
      "text": "Good. You’re cleared to go home. Take it easy, eat small meals, and don’t take pills on an empty stomach."
    },
    {
      "turn_number": 50,
      "time": "2125-02-17 07:26:00",
      "speaker": "Patient",
      "text": "Thank you, Dr. Lee. I feel much better already."
    },
    {
      "turn_number": 51,
      "time": "2125-02-17 07:28:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and we’ll see you at your follow-up."
    },
    {
      "turn_number": 52,
      "time": "2125-02-17 07:30:00",
      "speaker": "Patient",
      "text": "One more thing — my back pain is better, but should I restart my tramadol at home?"
    },
    {
      "turn_number": 53,
      "time": "2125-02-17 07:32:00",
      "speaker": "Doctor",
      "text": "Yes, as needed. Just don’t exceed one every four hours."
    },
    {
      "turn_number": 54,
      "time": "2125-02-17 07:34:00",
      "speaker": "Patient",
      "text": "And Zofran — same as before?"
    },
    {
      "turn_number": 55,
      "time": "2125-02-17 07:36:00",
      "speaker": "Doctor",
      "text": "Yes, one every six hours as needed for nausea. But call if you need it more than twice in a day."
    },
    {
      "turn_number": 56,
      "time": "2125-02-17 07:38:00",
      "speaker": "Patient",
      "text": "Understood. I’ll play it safe."
    },
    {
      "turn_number": 57,
      "time": "2125-02-17 07:40:00",
      "speaker": "Doctor",
      "text": "Good plan. We’ll get your discharge papers ready."
    },
    {
      "turn_number": 58,
      "time": "2125-02-17 07:42:00",
      "speaker": "Patient",
      "text": "Thanks again for helping me feel better."
    },
    {
      "turn_number": 59,
      "time": "2125-02-17 07:44:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care of yourself."
    },
    {
      "turn_number": 60,
      "time": "2125-02-17 07:46:00",
      "speaker": "Patient",
      "text": "I will."
    }
  ],
  "summary": {
    "admission_start": "2125-02-16 00:19:00",
    "admission_end": "2125-02-17 11:50:00",
    "summary_paragraph": "A woman with type 1 diabetes and a history of gastroparesis was admitted for recurrent nausea and vomiting that began after taking morning medications on an empty stomach. She had no abdominal pain or signs of infection, and labs showed no metabolic derangement. Her symptoms improved with bowel rest, IV fluids, and symptom management. The hospital course was complicated by hypoglycemia due to reduced oral intake, prompting a temporary reduction in her evening Lantus insulin from 28 to 24 units. She gradually advanced to a regular diet, remained nausea-free, and was discharged home with instructions to resume her normal insulin dose when eating normally and to follow up with her primary care provider.",
    "problems": [
      "Nausea with vomiting",
      "Diabetes with other specified manifestations, type I [juvenile type], uncontrolled",
      "Diabetes with renal manifestations, type I [juvenile type], uncontrolled",
      "Nephritis and nephropathy, not specified as acute or chronic, in diseases classified elsewhere",
      "Other chronic pain",
      "Backache, unspecified",
      "Panic disorder without agoraphobia",
      "Depressive disorder, not elsewhere classified",
      "Diabetes with neurological manifestations, type I [juvenile type], uncontrolled",
      "Gastroparesis"
    ]
  }
}
